以下是一个完整的 Python 函数集合，用于计算斐波那契数列的第 n 项，涵盖多种实现方法，并附带性能对比与使用建议：

```python
def fibonacci_iterative(n):
    """迭代法 - 推荐方式（效率高）"""
    if n < 0:
        raise ValueError("n 必须是非负整数")

    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def fibonacci_recursive(n):
    """递归法 - 简单但效率低（推荐仅用于教学）"""
    if n < 0:
        raise ValueError("n 必须是非负整数")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)


def fibonacci_memoized(n, memo=None):
    """记忆化递归法 - 效率较高"""
    if memo is None:
        memo = {}

    if n < 0:
        raise ValueError("n 必须是非负整数")

    if n in memo:
        return memo[n]

    if n == 0:
        result = 0
    elif n == 1:
        result = 1
    else:
        result = fibonacci_memoized(n - 1, memo) + fibonacci_memoized(n - 2, memo)

    memo[n] = result
    return result


def fibonacci_fast_doubling(n):
    """快速倍增法 - 最优算法 O(log n)"""
    def fib_pair(k):
        if k == 0:
            return (0, 1)
        a, b = fib_pair(k >> 1)
        c = a * ((b << 1) - a)
        d = b * b + a * a
        if k & 1:
            return (d, c + d)
        else:
            return (c, d)

    _, result = fib_pair(n)
    return result


def fibonacci_closed_formula(n):
    """快速公式法（O(1)，但存在浮点精度问题）"""
    if n < 0:
        raise ValueError("n 必须是非负整数")
    import math
    phi = (1 + 5 ** 0.5) / 2
    result = round((phi ** n) - ((-1 / phi) ** n)) // 36
    # 注意：该算法不适用于大 n，容易有精度误差
    return result


# 测试函数
if __name__ == "__main__":
    test_values = [0, 1, 2, 5, 10, 20]
    print("斐波那契数列前 N 项测试结果：\n")
    for val in test_values:
        try:
            res = fibonacci_iterative(val)
            print(f"F({val}) = {res}")
        except Exception as e:
            print(f"错误：{e}")
```

